            new_r[i] = radii[i] + (m - radii[i]) * growth
            if new_r[i] < 0:
                new_r[i] = 0.0
        radii = new_r
        for _ in range(resolve_passes):
            changed = False
            for i in range(n):
                x, y = centers[i]
                w = min(x, 1 - x, y, 1 - y)
                if radii[i] > w:
                    radii[i] = w
