import math

N = 13

def pseudo_rand(seed):
    x = math.sin(seed * 12.9898) * 43758.5453
    return x - math.floor(x)

def compute_radii(cx, cy, iters):
    r = [0.0] * N
    for _ in range(iters):
        newr = [0.0] * N
        for i in range(N):
            best = min(cx[i], 1.0 - cx[i], cy[i], 1.0 - cy[i])
            for j in range(N):
                if j == i:
                    continue
                d = math.hypot(cx[i] - cx[j], cy[i] - cy[j])
                avail = d - r[j]
                if avail < best:
                    best = avail
            newr[i] = max(0.0, best)
        r = newr
    return r

def binding_constraint(i, cx, cy, r):
    walls = {'L': cx[i], 'R': 1.0 - cx[i], 'B': cy[i], 'T': 1.0 - cy[i]}
    best_kind, best_val, best_j = None, None, None
    for k, v in walls.items():
        if best_val is None or v < best_val:
            best_val, best_kind, best_j = v, k, None
    for j in range(N):
        if j == i:
            continue
        d = math.hypot(cx[i] - cx[j], cy[i] - cy[j])
        avail = d - r[j]
        if avail < best_val:
            best_val, best_kind, best_j = avail, 'N', j
    return best_kind, best_j

def optimize(cx, cy, outer_iters, step_hi, step_lo, sub_iters):
    cx, cy = cx[:], cy[:]
    for it in range(outer_iters):
        r = compute_radii(cx, cy, sub_iters)
        step = step_hi * (1.0 - it / outer_iters) + step_lo
        newcx, newcy = cx[:], cy[:]
        for i in range(N):
            kind, j = binding_constraint(i, cx, cy, r)
            dx = dy = 0.0
            if kind == 'L':
                dx = 1.0
            elif kind == 'R':
                dx = -1.0
            elif kind == 'B':
                dy = 1.0
            elif kind == 'T':
                dy = -1.0
            elif kind == 'N':
                ddx, ddy = cx[i] - cx[j], cy[i] - cy[j]
                d = math.hypot(ddx, ddy)
                if d > 1e-9:
                    dx, dy = ddx / d, ddy / d
            newcx[i] = min(1.0, max(0.0, cx[i] + step * dx))
            newcy[i] = min(1.0, max(0.0, cy[i] + step * dy))
        cx, cy = newcx, newcy
    return cx, cy

def init_random(seed_base):
    cx = [0.1 + 0.8 * pseudo_rand(seed_base + 2 * i + 1) for i in range(N)]
    cy = [0.1 + 0.8 * pseudo_rand(seed_base + 2 * i + 2) for i in range(N)]
    return cx, cy

def init_rows(row_counts, jitter_seed):
    cx, cy = [], []
    nrows = len(row_counts)
    for ridx, cnt in enumerate(row_counts):
        y = (ridx + 0.5) / nrows
        for cidx in range(cnt):
            x = (cidx + 0.5) / cnt
            jx = jy = 0.0
            if jitter_seed:
                jx = (pseudo_rand(jitter_seed + ridx * 13 + cidx) - 0.5) * 0.03
                jy = (pseudo_rand(jitter_seed + ridx * 29 + cidx + 5) - 0.5) * 0.03
            cx.append(min(0.99, max(0.01, x + jx)))
            cy.append(min(0.99, max(0.01, y + jy)))
    return cx, cy

