for idx, rp in enumerate([[4, 5, 4], [3, 4, 3, 3], [4, 4, 5], [3, 3, 4, 3], [4, 3, 3, 3]]):
    candidates.append(init_rows(rp, 0))
    candidates.append(init_rows(rp, 101 + idx))
