for cx0, cy0 in candidates:
    cx, cy = optimize(cx0, cy0, outer_iters=1200, step_hi=0.02, step_lo=0.0004, sub_iters=15)
    total = sum(compute_radii(cx, cy, 40))
    if best_total is None or total > best_total:
