class Rng:
    def __init__(self, seed):
        self.state = seed & 0x7FFFFFFF

    def next(self):
        self.state = (1103515245 * self.state + 12345) & 0x7FFFFFFF
        return self.state / 0x7FFFFFFF

    def uniform(self, a, b):
        return a + (b - a) * self.next()


def dist(p, q):
    return math.hypot(p[0] - q[0], p[1] - q[1])


def build_initial_centers():
    row_counts = [5, 5, 6, 5, 5, 5]
    R = len(row_counts)
    centers = []
    for i, c in enumerate(row_counts):
        y = (i + 1) / (R + 1)
        for j in range(c):
            x = (j + 1) / (c + 1)
            centers.append([x, y])
    return centers


def grow_sweep(centers, radii):
    for i in range(N):
        cx, cy = centers[i]
        max_r = min(cx, 1.0 - cx, cy, 1.0 - cy)
        for j in range(N):
            if j == i:
                continue
            d = dist(centers[i], centers[j])
            cand = d - radii[j]
            if cand < max_r:
                max_r = cand
        radii[i] = max_r if max_r > 0.0 else 0.0


def total(radii):
    s = 0.0
    for r in radii:
        s += r
    return s


def main():
    centers = build_initial_centers()
    radii = [0.0] * N

    for _ in range(300):
        grow_sweep(centers, radii)

    rng = Rng(20260818)
    iterations = 2500

    for it in range(iterations):
        i = int(rng.next() * N)
        if i >= N:
            i = N - 1

        scale = 0.12 * (1.0 - it / iterations) + 0.004

        old_center_i = centers[i][:]
        old_radii = radii[:]
        old_sum = total(old_radii)

        dx = rng.uniform(-scale, scale)
        dy = rng.uniform(-scale, scale)

        nx = centers[i][0] + dx
        ny = centers[i][1] + dy
        if nx < 1e-6:
            nx = 1e-6
        if nx > 1.0 - 1e-6:
            nx = 1.0 - 1e-6
        if ny < 1e-6:
            ny = 1e-6
        if ny > 1.0 - 1e-6:
            ny = 1.0 - 1e-6

        centers[i][0] = nx
        centers[i][1] = ny

        cx, cy = centers[i]
        max_r = min(cx, 1.0 - cx, cy, 1.0 - cy)
        for j in range(N):
            if j == i:
                continue
            d = dist(centers[i], centers[j])
            cand = d - radii[j]
            if cand < max_r:
                max_r = cand
        radii[i] = max_r if max_r > 0.0 else 0.0

        for j in range(N):
            if j == i:
                continue
            d = dist(centers[i], centers[j])
            limit = d - radii[i]
            if radii[j] > limit:
                radii[j] = limit if limit > 0.0 else 0.0

        for _ in range(2):
            grow_sweep(centers, radii)

        new_sum = total(radii)

        if new_sum <= old_sum + 1e-12:
            centers[i][0] = old_center_i[0]
            centers[i][1] = old_center_i[1]
            radii = old_radii

    for _ in range(200):
        grow_sweep(centers, radii)

    eps = 1e-9
    result = []
    for i in range(N):
        r = radii[i] - eps
        if r < 0.0:
            r = 0.0
        result.append([centers[i][0], centers[i][1], r])

    print(result)


